## Submitted testbench
```systemverilog
module tb;

  // -------------------------------------------------
  // Parameters and clock
  // -------------------------------------------------
  localparam int CLK_PERIOD = 8;                     // 125 MHz
  localparam logic [15:0] PRESCALE_VAL = 16'h5;      // prescale = 5 (baseline)

  // -------------------------------------------------
  // DUT signals
  // -------------------------------------------------
  logic        clk;
  logic        rst;
  logic        rxd;
  logic [15:0] prescale = PRESCALE_VAL;

  // -------------------------------------------------
  // Top‑level module instantiation (default parameters)
  // -------------------------------------------------
  uart #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .rxd          (rxd),
    .prescale     (prescale),
    .s_axis_tdata (8'h00),
    .s_axis_tvalid(1'b0),
    .s_axis_tready(),
    .m_axis_tdata (),
    .m_axis_tvalid(),
    .m_axis_tready(),
    .txd          (),
    .tx_busy      (),
    .rx_busy      (),
    .rx_overrun_error(),
    .rx_frame_error()
  );

  // -------------------------------------------------
  // Clock generation
  // -------------------------------------------------
  initial begin
    clk = 1'b0;
    forever #(CLK_PERIOD/2) clk = ~clk;
  end

  // -------------------------------------------------
  // Reset sequence
  // -------------------------------------------------
  initial begin
    rst = 1'b0;
    #(CLK_PERIOD*2);
    rst = 1'b1;
    #(CLK_PERIOD*2);
    rst = 1'b0;
    #(CLK_PERIOD*2);
  end

  // -------------------------------------------------
  // Helper tasks
  // -------------------------------------------------
  task automatic wait_neg(input int cnt);
    repeat (cnt) @(negedge clk);
  endtask

  // -------------------------------------------------
  // Byte‑level transmitter (uses the design’s prescale)
  // -------------------------------------------------
  task automatic send_byte(input byte unsigned b);
    int bit_clks;
    bit_clks = int'(prescale) * 8;

    // start bit (low)
    rxd = 1'b0;
    repeat (bit_clks) @(negedge clk);

    // data bits (LSB first)
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];
      repeat (bit_clks) @(negedge clk);
    end

    // stop bit (high)
    rxd = 1'b1;
    repeat (bit_clks) @(negedge clk);
  endtask

  // -------------------------------------------------
  // Test‑bench state and monitoring
  // -------------------------------------------------
  // Wait for the first word to be delivered, then start the second
  // frame exactly two clocks later.
  logic first_seen = 1'b0;
  int   delay_cnt  = 0;

  // Detect when the second frame appears (8'h5A, no frame error) and finish.
  always @(posedge clk) begin
    if (first_seen && dut.uart_rx_inst.m_axis_tvalid &&
        dut.uart_rx_inst.m_axis_tdata == 8'h5A &&
        !dut.uart_rx_inst.frame_error) begin
      #1;               // let coverage be recorded on this edge
      $finish;
    end
  end

  // Edge detector for m_axis_tvalid from the RX instance.
  always @(posedge clk) begin
    if (!first_seen && dut.uart_rx_inst.m_axis_tvalid) begin
      first_seen <= 1'b1;
      delay_cnt  <= 2;               // 1 or 2 clock cycles → accept next start bit
    end else if (delay_cnt > 0) begin
      delay_cnt <= delay_cnt - 1;
      if (delay_cnt == 0) begin
        // Launch the second frame (payload = 0x5A)
        send_byte(8'h5A);
      end
    end
  end

  // -------------------------------------------------
  // Initial block – drive the first byte and start simulation
  // -------------------------------------------------
  initial begin
    // Wait until reset is released before driving the bus
    wait (!rst);
    #(CLK_PERIOD*5);               // small idle

    // Send an arbitrary first payload (any byte will do)
    send_byte(8'h3C);

    // The rest of the work is done by the monitors above.
    // No further stimulus is required – $finish will be called when
    // the coverage point R14_short_stop_back_to_back is hit.
  end

endmodule
